    internal sealed class ImageWorkspacePage:Grid,IDisposable
    {
        readonly PetWindow pet;readonly ComboBox providers,size,quality;readonly TextBox prompt,search;readonly CheckBox referenceOption;
        readonly StackPanel generated=new StackPanel(),galleryStatus=new StackPanel(),referencePreview=new StackPanel();readonly ImageGalleryPanel gallery=new ImageGalleryPanel{Margin=new Thickness(0,8,0,12)};Button masonryMode,gridMode;readonly ContentControl page=new ContentControl();readonly TextBlock notice,referenceLabel;readonly Button start,upload;readonly SettingsPageHeader heading;
        readonly DispatcherTimer timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};readonly Stopwatch elapsed=new Stopwatch();CancellationTokenSource cancellation;string imageJobId;byte[] reference;string referenceMedia="image/png";bool disposed,missingReference;string referenceId;int galleryLimit=40;
        internal ImageWorkspacePage(PetWindow owner)
        {
            pet=owner;Name="ImageWorkspacePage";Margin=new Thickness(24,22,24,16);RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});RowDefinitions.Add(new RowDefinition());
            heading=new SettingsPageHeader("图像","写下提示词，生成图片；图库收录本页和对话中的生成结果。",new[]{"生成","图库"},new[]{"ImageGenerateTab","ImageGalleryTab"}){Margin=new Thickness(0,0,0,16)};Children.Add(heading);Grid.SetRow(page,1);Children.Add(page);
            var form=new StackPanel();providers=new ComboBox{Name="ImageServicePicker",MinHeight=38,Padding=new Thickness(8)};providers.SelectionChanged+=delegate{var p=providers.SelectedItem as ImageGenerationProvider;if(p!=null){size.ItemsSource=new[]{"服务默认"}.Concat(ImageServicePresets.Sizes(p.Protocol)).ToArray();quality.ItemsSource=new[]{"服务默认"}.Concat(ImageServicePresets.Qualities(p.Protocol)).ToArray();size.Text=String.IsNullOrEmpty(p.Size)?"服务默认":p.Size;quality.Text=String.IsNullOrEmpty(p.Quality)?"服务默认":p.Quality;}RefreshReferenceAvailability();};Ui.Label(form,"生图服务 / 模型",providers);
            var configure=Ui.Button("配置生图服务");configure.Name="ConfigureImageService";configure.HorizontalAlignment=HorizontalAlignment.Left;configure.Click+=delegate{pet.ShowImageConfiguration();};form.Children.Add(configure);
            prompt=Ui.Field("",true);prompt.Name="ImagePrompt";prompt.MinHeight=120;prompt.MaxLength=16000;Ui.Label(form,"提示词",prompt);
            size=ImageGenerationSettings.DefaultChoices(new[]{"1024x1024","1536x1024","1024x1536","auto"});size.Name="ImageSize";quality=ImageGenerationSettings.DefaultChoices(new[]{"auto","low","medium","high","standard","hd"});quality.Name="ImageQuality";Ui.Label(form,"尺寸（可不指定）",size);Ui.Label(form,"质量 / 分辨率（可不指定）",quality);
            var referenceActions=new WrapPanel();upload=Ui.Button("上传参考图");upload.Name="ImageReferenceUpload";upload.Click+=delegate{PickReference();};referenceActions.Children.Add(upload);var remove=Ui.Button("移除参考图");remove.Click+=delegate{reference=null;referenceId=null;missingReference=false;referencePreview.Children.Clear();RefreshReferenceAvailability();};referenceActions.Children.Add(remove);form.Children.Add(referenceActions);referenceLabel=Ui.Text("",11,Ui.Muted);form.Children.Add(referenceLabel);form.Children.Add(referencePreview);referenceOption=new CheckBox{Content="参考图将上传至所选生图服务",Visibility=Visibility.Collapsed,IsChecked=true};form.Children.Add(referenceOption);
            var actions=new WrapPanel{Margin=new Thickness(0,12,0,0)};start=Ui.Button("生成图片",true);start.Name="StartImageGeneration";start.Click+=async delegate{await GenerateAsync();};actions.Children.Add(start);var cancel=Ui.Button("取消生成");cancel.Name="CancelImageGeneration";cancel.Click+=delegate{if(imageJobId!=null)pet.ImageTasks.CancelAsync(imageJobId);};actions.Children.Add(cancel);form.Children.Add(actions);notice=Ui.Text("",12,Ui.Muted);notice.Name="ImageGenerationStatus";form.Children.Add(notice);form.Children.Add(generated);
            var galleryBody=new StackPanel();var layouts=new WrapPanel{Margin=new Thickness(0,0,0,12)};masonryMode=Ui.Button("瀑布流");masonryMode.Name="GalleryMasonryLayout";gridMode=Ui.Button("等大网格");gridMode.Name="GalleryGridLayout";masonryMode.Click+=delegate{SetGalleryMode("masonry");};gridMode.Click+=delegate{SetGalleryMode("grid");};layouts.Children.Add(masonryMode);layouts.Children.Add(gridMode);galleryBody.Children.Add(layouts);search=Ui.Field("");search.Name="ImageGallerySearch";Ui.Label(galleryBody,"搜索提示词或模型",search);search.TextChanged+=delegate{galleryLimit=40;RefreshGallery();};galleryBody.Children.Add(galleryStatus);galleryBody.Children.Add(gallery);var recover=Ui.Button("恢复图库索引");recover.Name="RecoverImageGallery";recover.Click+=delegate{try{int count=pet.ImageStore.Recover();notice.Text="已恢复 "+count+" 项图片记录。";RefreshGallery();}catch(Exception){notice.Text="恢复失败，原文件已保留，请检查存储目录。";}};galleryBody.Children.Add(recover);var more=Ui.Button("加载更多");more.Click+=delegate{galleryLimit+=40;RefreshGallery();};galleryBody.Children.Add(more);
            var formScroll=Ui.Scroll(form);var galleryScroll=Ui.Scroll(galleryBody);heading.SelectionChanged+=index=>{page.Content=index==0?formScroll:galleryScroll;if(index==1)RefreshGallery();};heading.Select(0);
            timer.Tick+=delegate{notice.Text="正在生成图片 · "+(int)elapsed.Elapsed.TotalSeconds+" 秒";};Loaded+=delegate{RefreshProviders();};pet.ImageStore.Changed+=StoreChanged;
        }
        internal void Prepare(GeneratedImage image)
        {
            heading.Select(0);RefreshProviders();if(image==null)return;var p=pet.Settings.ImageProviders.FirstOrDefault(v=>v.Id==image.ProviderId);if(p!=null)providers.SelectedItem=p;prompt.Text=image.Prompt;size.Text=String.IsNullOrEmpty(image.Size)?"服务默认":image.Size;quality.Text=String.IsNullOrEmpty(image.Quality)?"服务默认":image.Quality;
            reference=null;referenceId=null;missingReference=false;referencePreview.Children.Clear();notice.Text="已填入原提示词和参数，点击“生成图片”发起新的请求。";
            if(!String.IsNullOrEmpty(image.ReferenceImageId))try{var original=pet.ImageStore.Get(image.ReferenceImageId);reference=pet.ImageStore.Read(image.ReferenceImageId);referenceId=image.ReferenceImageId;referenceMedia=original.MediaType;int width,height;bool limited;var bitmap=ChatImagePreview.DecodeGeneratedImage(reference,220,out width,out height,out limited);referencePreview.Children.Add(new Image{Source=bitmap,MaxHeight=130,HorizontalAlignment=HorizontalAlignment.Left});}catch(Exception error){if(!(error is IOException||error is UnauthorizedAccessException||error is ArgumentException))throw;reference=null;missingReference=true;notice.Text="原参考图缺失，请重新上传或明确移除后再生成。";}
            RefreshReferenceAvailability();
        }
        internal void RefreshProviders(){string selected=(providers.SelectedItem as ImageGenerationProvider??pet.Settings.SelectedImageProvider())==null?null:(providers.SelectedItem as ImageGenerationProvider??pet.Settings.SelectedImageProvider()).Id;providers.ItemsSource=null;providers.ItemsSource=pet.Settings.ImageProviders;providers.SelectedItem=pet.Settings.ImageProviders.FirstOrDefault(p=>p.Id==selected)??pet.Settings.SelectedImageProvider();RefreshReferenceAvailability();}
        void RefreshReferenceAvailability(){if(upload==null||referenceLabel==null)return;var p=providers.SelectedItem as ImageGenerationProvider;upload.IsEnabled=p!=null&&p.SupportsEdits&&cancellation==null;referenceLabel.Text=reference!=null?"已选择参考图 · "+(reference.Length/1024)+" KB":p==null?"请先配置并选择生图服务。":!p.SupportsEdits?"此服务尚未启用参考图编辑；可在图片生成配置中启用。":"可选：上传一张 PNG、JPEG 或 WebP 参考图。";}
        void PickReference(){var picker=new Microsoft.Win32.OpenFileDialog{Title="选择参考图",Filter="图片|*.png;*.jpg;*.jpeg;*.webp",Multiselect=false};if(picker.ShowDialog(Window.GetWindow(this))!=true)return;try{var info=new FileInfo(picker.FileName);if(info.Length>50L*1024*1024)throw new InvalidOperationException("参考图不能超过 50 MB。");byte[] bytes=File.ReadAllBytes(info.FullName);int width,height;bool limited;var bitmap=ChatImagePreview.DecodeGeneratedImage(bytes,220,out width,out height,out limited);reference=bytes;referenceId=null;missingReference=false;referenceMedia=info.Extension.ToLowerInvariant()==".webp"?"image/webp":info.Extension.ToLowerInvariant()==".png"?"image/png":"image/jpeg";referencePreview.Children.Clear();referencePreview.Children.Add(new Image{Source=bitmap,MaxHeight=130,HorizontalAlignment=HorizontalAlignment.Left});RefreshReferenceAvailability();}catch(Exception e){notice.Text=e is InvalidOperationException?e.Message:"参考图无法读取，请选择有效图片。";}}
        internal async Task GenerateAsync(){if(cancellation!=null)return;var provider=providers.SelectedItem as ImageGenerationProvider;if(provider==null){notice.Text="请先配置并选择生图服务。";return;}if(String.IsNullOrWhiteSpace(prompt.Text)){notice.Text="请填写提示词。";return;}if(missingReference){notice.Text="原参考图缺失，请重新上传或明确移除参考图。";return;}if(reference!=null&&!provider.SupportsEdits){notice.Text="当前服务未启用参考图编辑，请移除参考图或切换服务。";return;}var c=new CancellationTokenSource();cancellation=c;start.IsEnabled=false;elapsed.Restart();timer.Start();RefreshReferenceAvailability();notice.Text="正在生成图片 · 0 秒";
            try{var request=new ImageGenerationRequest{Provider=provider.Copy(),Prompt=prompt.Text,Size=ImageGenerationSettings.Optional(size),Quality=ImageGenerationSettings.Optional(quality),ReferenceImageBytes=reference,ReferenceMediaType=referenceMedia,ReferenceImageId=referenceId,SessionId="image-workspace",Persistent=pet.Settings.SaveChatHistory};var handle=await pet.ImageTasks.EnqueueAsync(new ImageGenerationTaskSubmission(Guid.NewGuid().ToString("N"),request,new ImageTaskOrigin{Source=ImageGenerationSource.Workspace}) { BeforeStart = id => { imageJobId=id; return Task.FromResult(0); } },CancellationToken.None);var image=await handle.Completion;if(!disposed){generated.Children.Clear();generated.Children.Add(new GeneratedImageCard(pet,Window.GetWindow(this),image,Prepare));notice.Text="图片已生成并保存 · "+(int)elapsed.Elapsed.TotalSeconds+" 秒";}}
            catch(OperationCanceledException){if(!disposed)notice.Text="已取消生成。";}catch(Exception e){if(!disposed)notice.Text=e is ApiException||e is InvalidOperationException||e is TimeoutException||e is IOException?e.Message:"生成失败，请检查生图服务和本地存储。";}finally{timer.Stop();elapsed.Stop();if(ReferenceEquals(cancellation,c))cancellation=null;c.Dispose();start.IsEnabled=true;RefreshReferenceAvailability();}}
        void StoreChanged(){if(disposed||Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke(new Action(delegate{if(!disposed)RefreshGallery();}));}
        void RefreshGallery(){if(disposed||search==null)return;gallery.Children.Clear();galleryStatus.Children.Clear();gallery.Mode=pet.Settings.ImageGalleryLayout;SetLayoutButton(masonryMode,gallery.Mode=="masonry");SetLayoutButton(gridMode,gallery.Mode=="grid");System.Windows.Automation.AutomationProperties.SetItemStatus(masonryMode,gallery.Mode=="masonry"?"已选中":"");System.Windows.Automation.AutomationProperties.SetItemStatus(gridMode,gallery.Mode=="grid"?"已选中":"");string query=search.Text.Trim();var items=pet.ImageStore.List().Where(i=>query.Length==0||(i.Prompt??"").IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||(i.Model??"").IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).OrderByDescending(i=>i.CreatedUtc).Take(galleryLimit).ToList();if(items.Count==0)galleryStatus.Children.Add(Ui.Text("图库中还没有图片。生成一张后会显示在这里。",12,Ui.Muted));foreach(var image in items)gallery.Children.Add(new ImageGalleryTile(pet,image,gallery.Mode,Prepare));if(!String.IsNullOrEmpty(pet.ImageStore.Warning))galleryStatus.Children.Add(Ui.Text(pet.ImageStore.Warning,12,Ui.Muted));}
        void SetGalleryMode(string mode){pet.Settings.ImageGalleryLayout=mode;pet.SaveSettings();RefreshGallery();}
        static void SetLayoutButton(Button button,bool selected){button.Background=selected?Ui.Pale:System.Windows.Media.Brushes.Transparent;button.Foreground=selected?Ui.Blue:Ui.Muted;button.FontWeight=selected?FontWeights.SemiBold:FontWeights.Normal;}
        public void Dispose(){if(disposed)return;disposed=true;pet.ImageStore.Changed-=StoreChanged;timer.Stop();}
